/**
 * Conduit — Project Scenario Modelling
 * Restricted: internal use only (Hein, Lew, Hanro)
 */

import { Lock, TrendingUp } from 'lucide-react';
import { PortfolioTable } from '@/modules/conduit/components/PortfolioTable';
import type { ConduitProject } from '@/modules/conduit/types';

async function getProjects(): Promise<ConduitProject[]> {
  try {
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3005';
    const res = await fetch(`${baseUrl}/api/conduit/projects`, {
      cache: 'no-store',
    });
    if (!res.ok) return [];
    const { data } = await res.json() as { data: ConduitProject[] };
    return data ?? [];
  } catch {
    return [];
  }
}

export default async function ConduitPage() {
  const projects = await getProjects();

  return (
    <div className="p-6 space-y-6 min-h-screen bg-gray-950">
      {/* Header */}
      <div className="flex items-center gap-3">
        <TrendingUp className="w-7 h-7 text-teal-400" />
        <div>
          <h1 className="text-2xl font-bold text-white">Conduit</h1>
          <p className="text-sm text-gray-400 flex items-center gap-1">
            <Lock className="w-3 h-3" />
            Project scenario modelling — Internal use only
          </p>
        </div>
      </div>

      {/* Portfolio table */}
      {projects.length === 0 ? (
        <div className="rounded-lg border border-gray-700 bg-gray-800 p-12 text-center text-gray-400">
          <TrendingUp className="w-12 h-12 mx-auto mb-3 opacity-30" />
          <p className="text-lg font-medium">No projects yet</p>
          <p className="text-sm mt-1 text-gray-500">
            Run migration 249 to seed the Lawley test case.
          </p>
        </div>
      ) : (
        <PortfolioTable initialProjects={projects} />
      )}
    </div>
  );
}

/**
 * useConduitCalc — Pure formula engine for Conduit project calculations.
 * No side effects, no API calls. Input → derived output.
 *
 * COS Formula:
 *   Services = (Poles × PermPerPole) + (Poles × PolesEach) + (Stringing × StringPerM)
 *              + (PON × OptPerPON) + (FCActivations × ActEach)
 *   Stock    = (Poles × PoleStock) + (Stringing × CablePerM)
 *              + (PON × OptStock) + (FCActivations × ActStock)
 *   Expenses = (AdHoc + Casuals + Fuel + Overheads + Sales) × BuildDuration
 *   COS Total = Services + Stock + Expenses
 */

import type { ConduitProject, ConduitCalcResult } from '../types';

export function calcConduit(project: ConduitProject): ConduitCalcResult {
  const { po_count, build_duration_months, inputs_json: inp } = project;
  const { rate, uptake, scope, service_rates: sr, stock_rates: st, expenses_per_month: ex } = inp;

  // Core derivations
  const fc_activation = po_count * uptake;
  const revenue = fc_activation * rate * 12;

  // COS — Services
  const cos_services =
    scope.poles * sr.permissions_per_pole +
    scope.poles * sr.poles_each +
    scope.stringing_m * sr.stringing_per_m +
    scope.pon * sr.optical_per_pon +
    fc_activation * sr.activation_each;

  // COS — Stock
  const cos_stock =
    scope.poles * st.pole +
    scope.stringing_m * st.cable_per_m +
    scope.pon * st.optical +
    fc_activation * st.activation;

  // COS — Expenses (monthly total × build duration)
  const monthly_expenses = ex.ad_hoc + ex.casuals + ex.fuel + ex.overheads + ex.sales;
  const cos_expenses = monthly_expenses * build_duration_months;

  const cos_total = cos_services + cos_stock + cos_expenses;
  const profit = revenue - cos_total;
  const gross_profit_pct = revenue > 0 ? profit / revenue : 0;
  const cost_per_home = po_count > 0 ? cos_total / po_count : 0;

  return {
    fc_activation,
    revenue,
    cos_services,
    cos_stock,
    cos_expenses,
    cos_total,
    profit,
    gross_profit_pct,
    cost_per_home,
  };
}

/** React hook wrapper — memoises calc result when project changes. */
import { useMemo } from 'react';

export function useConduitCalc(project: ConduitProject): ConduitCalcResult {
  return useMemo(() => calcConduit(project), [project]);
}

/**
 * Conduit module types — project scenario modelling.
 */

export interface ScopeInputs {
  poles: number;
  stringing_m: number;
  pon: number;
}

export interface ServiceRates {
  permissions_per_pole: number;
  poles_each: number;
  stringing_per_m: number;
  optical_per_pon: number;
  activation_each: number;
}

export interface StockRates {
  pole: number;
  cable_per_m: number;
  optical: number;
  activation: number;
}

export interface ExpensesPerMonth {
  ad_hoc: number;
  casuals: number;
  fuel: number;
  overheads: number;
  sales: number;
}

export interface ConduitProjectInputs {
  rate: number;
  uptake: number;
  scope: ScopeInputs;
  service_rates: ServiceRates;
  stock_rates: StockRates;
  expenses_per_month: ExpensesPerMonth;
}

export interface ConduitProject {
  id: string;
  name: string;
  po_count: number;
  start_date: string | null;
  build_duration_months: number;
  inputs_json: ConduitProjectInputs;
  is_baseline_locked: boolean;
  created_at: string;
  updated_at: string;
}

/** Calculated (derived) fields — never stored, always re-derived from inputs */
export interface ConduitCalcResult {
  fc_activation: number;
  revenue: number;
  cos_services: number;
  cos_stock: number;
  cos_expenses: number;
  cos_total: number;
  profit: number;
  gross_profit_pct: number;
  cost_per_home: number;
}

/**
 * PortfolioTable — Inline-editable project summary table.
 *
 * Editable cells (white bg): Name, PO Count, Rate, Uptake %, Build Duration, Start Date
 * Calculated cells (pale green): FC Activation, Revenue, COS Total, Profit, GP%, Cost/Home
 *
 * Click any editable cell → edit in place → blur → instant recalculate.
 * [Save] button persists all changes to the API.
 */

'use client';

import { useState, useRef, useCallback } from 'react';
import { Save, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import type { ConduitProject, ConduitProjectInputs } from '../types';
import { calcConduit } from '../hooks/useConduitCalc';

// ─── Formatting helpers ────────────────────────────────────────────────────

function fZAR(v: number): string {
  if (!isFinite(v)) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fPct(v: number): string {
  return `${(v * 100).toFixed(1)}%`;
}

function fNum(v: number): string {
  return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0');
}

// ─── Editable cell ────────────────────────────────────────────────────────

interface EditableCellProps {
  value: string | number;
  onCommit: (val: string) => void;
  type?: 'text' | 'number' | 'date' | 'percent';
  align?: 'left' | 'right';
  disabled?: boolean;
}

function EditableCell({ value, onCommit, type = 'number', align = 'right', disabled = false }: EditableCellProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const displayValue = type === 'percent'
    ? `${(Number(value) * 100).toFixed(1)}%`
    : type === 'number'
    ? fNum(Number(value))
    : String(value ?? '');

  const startEdit = () => {
    if (disabled) return;
    const raw = type === 'percent' ? String(Number(value) * 100) : String(value ?? '');
    setDraft(raw);
    setEditing(true);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commit = () => {
    setEditing(false);
    if (draft === String(value)) return;
    const committed = type === 'percent' ? String(Number(draft) / 100) : draft;
    onCommit(committed);
  };

  const tdClass = `px-3 py-2 text-sm ${align === 'right' ? 'text-right' : 'text-left'} bg-white border border-gray-200 cursor-text hover:bg-blue-50 transition-colors`;

  if (editing) {
    return (
      <td className={tdClass} style={{ minWidth: 80 }}>
        <input
          ref={inputRef}
          type={type === 'percent' ? 'number' : type}
          value={draft}
          onChange={e => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={e => { if (e.key === 'Enter') commit(); if (e.key === 'Escape') setEditing(false); }}
          className="w-full bg-transparent outline-none text-sm text-right font-medium text-gray-900"
          step={type === 'percent' ? '0.1' : undefined}
        />
      </td>
    );
  }

  return (
    <td className={tdClass} onClick={startEdit}>
      <span className="font-medium text-gray-900">{displayValue}</span>
    </td>
  );
}

// ─── Calculated cell ──────────────────────────────────────────────────────

function CalcCell({ value, format = 'zar', negative = false }: { value: number; format?: 'zar' | 'pct' | 'num'; negative?: boolean }) {
  const display = format === 'zar' ? fZAR(value) : format === 'pct' ? fPct(value) : fNum(value);
  const color = negative && value < 0 ? 'text-red-600' : negative && value > 0 ? 'text-emerald-700' : 'text-emerald-800';
  return (
    <td className="px-3 py-2 text-sm text-right bg-emerald-50 border border-emerald-100">
      <span className={`font-medium tabular-nums ${color}`}>{display}</span>
    </td>
  );
}

// ─── Main component ───────────────────────────────────────────────────────

interface PortfolioTableProps {
  initialProjects: ConduitProject[];
}

export function PortfolioTable({ initialProjects }: PortfolioTableProps) {
  const [projects, setProjects] = useState<ConduitProject[]>(initialProjects);
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState<Record<string, boolean>>({});
  const [error, setError] = useState<string | null>(null);

  // Deep-update a project field
  const updateProject = useCallback((id: string, updater: (p: ConduitProject) => ConduitProject) => {
    setProjects(prev => prev.map(p => p.id === id ? updater(p) : p));
    setSaved(prev => ({ ...prev, [id]: false }));
  }, []);

  const updateTopLevel = (id: string, field: keyof ConduitProject, raw: string) => {
    updateProject(id, p => ({ ...p, [field]: field === 'po_count' || field === 'build_duration_months' ? Number(raw) : raw }));
  };

  const updateInputs = (id: string, field: keyof ConduitProjectInputs, raw: string) => {
    updateProject(id, p => ({
      ...p,
      inputs_json: { ...p.inputs_json, [field]: Number(raw) },
    }));
  };

  const saveProject = async (project: ConduitProject) => {
    setSaving(prev => ({ ...prev, [project.id]: true }));
    setError(null);
    try {
      const res = await fetch(`/api/conduit/projects/${project.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: project.name,
          po_count: project.po_count,
          start_date: project.start_date,
          build_duration_months: project.build_duration_months,
          inputs_json: project.inputs_json,
          version_label: `Manual save ${new Date().toLocaleString('en-ZA')}`,
        }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { data } = await res.json() as { data: ConduitProject };
      setProjects(prev => prev.map(p => p.id === data.id ? data : p));
      setSaved(prev => ({ ...prev, [project.id]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [project.id]: false })), 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(prev => ({ ...prev, [project.id]: false }));
    }
  };

  // Header style
  const thClass = 'px-3 py-2.5 text-left text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';
  const thRightClass = `${thClass} text-right`;

  return (
    <div className="space-y-4">
      {error && (
        <div className="flex items-center gap-2 text-red-400 bg-red-400/10 border border-red-400/20 rounded px-3 py-2 text-sm">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          {error}
        </div>
      )}

      <div className="overflow-x-auto rounded-lg border border-gray-200 shadow-sm">
        <table className="min-w-max w-full border-collapse text-sm">
          {/* Column group labels */}
          <thead>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              <th className={thClass} colSpan={6}>INPUTS (editable)</th>
              <th className={`${thClass} text-right`} colSpan={6} style={{ backgroundColor: '#1e5440' }}>
                CALCULATED (live)
              </th>
              <th className={thClass} style={{ width: 80 }}></th>
            </tr>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              {/* Editable columns */}
              <th className={thClass} style={{ minWidth: 160 }}>Project</th>
              <th className={thRightClass} style={{ minWidth: 90 }}>PO Count</th>
              <th className={thRightClass} style={{ minWidth: 80 }}>Rate (R)</th>
              <th className={thRightClass} style={{ minWidth: 80 }}>Uptake %</th>
              <th className={thRightClass} style={{ minWidth: 100 }}>Build (mo)</th>
              <th className={thRightClass} style={{ minWidth: 120 }}>Start Date</th>
              {/* Calculated columns */}
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 110 }}>FC Activations</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>Revenue</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>COS Total</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>Profit</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 80 }}>GP %</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 110 }}>Cost / Home</th>
              {/* Actions */}
              <th className={thClass} style={{ minWidth: 72 }}></th>
            </tr>
          </thead>

          <tbody>
            {projects.map(project => {
              const calc = calcConduit(project);
              const isSaving = saving[project.id] ?? false;
              const justSaved = saved[project.id] ?? false;
              return (
                <tr key={project.id} className="hover:bg-gray-50/50">
                  {/* Editable cells */}
                  <EditableCell
                    value={project.name}
                    type="text"
                    align="left"
                    onCommit={v => updateTopLevel(project.id, 'name', v)}
                  />
                  <EditableCell
                    value={project.po_count}
                    onCommit={v => updateTopLevel(project.id, 'po_count', v)}
                  />
                  <EditableCell
                    value={project.inputs_json.rate}
                    onCommit={v => updateInputs(project.id, 'rate', v)}
                  />
                  <EditableCell
                    value={project.inputs_json.uptake}
                    type="percent"
                    onCommit={v => updateInputs(project.id, 'uptake', v)}
                  />
                  <EditableCell
                    value={project.build_duration_months}
                    onCommit={v => updateTopLevel(project.id, 'build_duration_months', v)}
                  />
                  <EditableCell
                    value={project.start_date ?? ''}
                    type="date"
                    align="left"
                    onCommit={v => updateTopLevel(project.id, 'start_date', v)}
                  />

                  {/* Calculated cells */}
                  <CalcCell value={calc.fc_activation} format="num" />
                  <CalcCell value={calc.revenue} />
                  <CalcCell value={calc.cos_total} />
                  <CalcCell value={calc.profit} negative />
                  <CalcCell value={calc.gross_profit_pct} format="pct" negative />
                  <CalcCell value={calc.cost_per_home} />

                  {/* Save button */}
                  <td className="px-2 py-2 text-center bg-white border border-gray-200">
                    <button
                      onClick={() => saveProject(project)}
                      disabled={isSaving || project.is_baseline_locked}
                      className="flex items-center gap-1 px-2 py-1 rounded text-xs font-medium bg-teal-700 hover:bg-teal-600 text-white disabled:opacity-40 transition-colors mx-auto"
                      title={project.is_baseline_locked ? 'Baseline locked' : 'Save changes'}
                    >
                      {isSaving ? (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      ) : justSaved ? (
                        <CheckCircle2 className="w-3 h-3 text-emerald-300" />
                      ) : (
                        <Save className="w-3 h-3" />
                      )}
                      {isSaving ? 'Saving' : justSaved ? 'Saved' : 'Save'}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>

          {/* Totals row */}
          {projects.length > 1 && (() => {
            const totals = projects.reduce((acc, p) => {
              const c = calcConduit(p);
              return {
                po_count: acc.po_count + p.po_count,
                fc_activation: acc.fc_activation + c.fc_activation,
                revenue: acc.revenue + c.revenue,
                cos_total: acc.cos_total + c.cos_total,
                profit: acc.profit + c.profit,
              };
            }, { po_count: 0, fc_activation: 0, revenue: 0, cos_total: 0, profit: 0 });
            const gp_pct = totals.revenue > 0 ? totals.profit / totals.revenue : 0;

            const totalTd = 'px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums';
            return (
              <tfoot>
                <tr style={{ backgroundColor: '#1a3a4a' }}>
                  <td className="px-3 py-2.5 text-sm font-bold text-white" colSpan={2}>TOTAL</td>
                  <td className={totalTd}>{fNum(totals.po_count)}</td>
                  <td colSpan={3}></td>
                  <td className={totalTd}>{fNum(totals.fc_activation)}</td>
                  <td className={totalTd}>{fZAR(totals.revenue)}</td>
                  <td className={totalTd}>{fZAR(totals.cos_total)}</td>
                  <td className={totalTd}>{fZAR(totals.profit)}</td>
                  <td className={totalTd}>{fPct(gp_pct)}</td>
                  <td colSpan={2}></td>
                </tr>
              </tfoot>
            );
          })()}
        </table>
      </div>

      <p className="text-xs text-gray-400">
        Click any white cell to edit. Calculated values update instantly. Press Save to persist.
      </p>
    </div>
  );
}

/**
 * GET  /api/conduit/projects  — list all conduit projects
 * POST /api/conduit/projects  — create a new project
 */

import { NextRequest, NextResponse } from 'next/server';
import { getAuth } from '@/lib/auth-mock';
import { neon } from '@neondatabase/serverless';
import type { ConduitProject } from '@/modules/conduit/types';

const sql = neon(process.env.DATABASE_URL!);

export async function GET(req: NextRequest) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const rows = await sql`
      SELECT id, name, po_count, start_date, build_duration_months,
             inputs_json, is_baseline_locked, created_at, updated_at
      FROM conduit_projects
      ORDER BY created_at ASC
    `;

    return NextResponse.json({ data: rows as ConduitProject[] });
  } catch (error) {
    console.error('[conduit/projects GET]', error);
    return NextResponse.json({ error: 'Failed to fetch projects' }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await req.json() as Partial<ConduitProject>;
    const { name, po_count, start_date, build_duration_months, inputs_json } = body;

    if (!name) {
      return NextResponse.json({ error: 'name is required' }, { status: 400 });
    }

    const [row] = await sql`
      INSERT INTO conduit_projects
        (name, po_count, start_date, build_duration_months, inputs_json)
      VALUES (
        ${name},
        ${po_count ?? 0},
        ${start_date ?? null},
        ${build_duration_months ?? 12},
        ${JSON.stringify(inputs_json ?? {})}::jsonb
      )
      RETURNING id, name, po_count, start_date, build_duration_months,
                inputs_json, is_baseline_locked, created_at, updated_at
    `;

    return NextResponse.json({ data: row as ConduitProject }, { status: 201 });
  } catch (error) {
    console.error('[conduit/projects POST]', error);
    return NextResponse.json({ error: 'Failed to create project' }, { status: 500 });
  }
}

/**
 * GET    /api/conduit/projects/[id] — fetch single project
 * PUT    /api/conduit/projects/[id] — update project + snapshot version history
 */

import { NextRequest, NextResponse } from 'next/server';
import { getAuth } from '@/lib/auth-mock';
import { neon } from '@neondatabase/serverless';
import type { ConduitProject } from '@/modules/conduit/types';

const sql = neon(process.env.DATABASE_URL!);

interface RouteContext {
  params: { id: string };
}

export async function GET(req: NextRequest, { params }: RouteContext) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const [row] = await sql`
      SELECT id, name, po_count, start_date, build_duration_months,
             inputs_json, is_baseline_locked, created_at, updated_at
      FROM conduit_projects
      WHERE id = ${params.id}
    `;

    if (!row) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    return NextResponse.json({ data: row as ConduitProject });
  } catch (error) {
    console.error('[conduit/projects/[id] GET]', error);
    return NextResponse.json({ error: 'Failed to fetch project' }, { status: 500 });
  }
}

export async function PUT(req: NextRequest, { params }: RouteContext) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await req.json() as Partial<ConduitProject> & { version_label?: string };
    const { name, po_count, start_date, build_duration_months, inputs_json, version_label } = body;

    // Fetch existing to snapshot before update
    const [existing] = await sql`
      SELECT * FROM conduit_projects WHERE id = ${params.id}
    `;

    if (!existing) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    if (existing.is_baseline_locked) {
      return NextResponse.json({ error: 'Project baseline is locked' }, { status: 409 });
    }

    // Snapshot current state as a version
    const label = version_label ?? `Auto-save ${new Date().toISOString()}`;
    await sql`
      INSERT INTO conduit_project_versions
        (project_id, version_label, inputs_snapshot, created_by)
      VALUES (
        ${params.id},
        ${label},
        ${JSON.stringify(existing.inputs_json)}::jsonb,
        ${auth.userId}
      )
    `;

    // Apply updates (only provided fields)
    const [updated] = await sql`
      UPDATE conduit_projects SET
        name                  = ${name ?? existing.name},
        po_count              = ${po_count ?? existing.po_count},
        start_date            = ${start_date ?? existing.start_date},
        build_duration_months = ${build_duration_months ?? existing.build_duration_months},
        inputs_json           = ${JSON.stringify(inputs_json ?? existing.inputs_json)}::jsonb
      WHERE id = ${params.id}
      RETURNING id, name, po_count, start_date, build_duration_months,
                inputs_json, is_baseline_locked, created_at, updated_at
    `;

    return NextResponse.json({ data: updated as ConduitProject });
  } catch (error) {
    console.error('[conduit/projects/[id] PUT]', error);
    return NextResponse.json({ error: 'Failed to update project' }, { status: 500 });
  }
}

/**
 * SharePoint Excel utility — reads ranges from the Shareholder Model workbook
 * via Microsoft Graph API using SHAREPOINT_* credentials (separate app from GRAPH_*).
 */

import { createLogger } from '@/lib/logger';

const logger = createLogger('graph:sharepoint-excel');

interface TokenCache {
  token: string;
  expiresAt: number;
}

/** Module-level token cache — survives across requests within the same Node.js process */
let spTokenCache: TokenCache | null = null;

/**
 * Acquires a Graph API access token using the SHAREPOINT_* app credentials.
 * Caches the token and refreshes 5 minutes before expiry.
 */
export async function getSharePointToken(): Promise<string> {
  if (spTokenCache && spTokenCache.expiresAt > Date.now() + 300_000) {
    return spTokenCache.token;
  }

  const tenantId = process.env.SHAREPOINT_TENANT_ID;
  const clientId = process.env.SHAREPOINT_CLIENT_ID;
  const clientSecret = process.env.SHAREPOINT_CLIENT_SECRET;

  if (!tenantId || !clientId || !clientSecret) {
    throw new Error(
      'Missing SharePoint credentials: SHAREPOINT_TENANT_ID, SHAREPOINT_CLIENT_ID, SHAREPOINT_CLIENT_SECRET required'
    );
  }

  const tokenUrl = `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`;
  const params = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  });

  const response = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`SharePoint OAuth failed: ${response.status} ${errorText}`);
  }

  const data = await response.json() as { access_token: string; expires_in: number };
  spTokenCache = {
    token: data.access_token,
    expiresAt: Date.now() + data.expires_in * 1000,
  };

  logger.info('SharePoint access token acquired', { expiresIn: data.expires_in });
  return spTokenCache.token;
}

/**
 * Fetches a worksheet's used range (or a specific address range) from the
 * Shareholder Model Excel file.
 *
 * @param worksheet - Worksheet name, e.g. "Financial Summary"
 * @param range - Optional A1-notation range, e.g. "A1:Z100". Defaults to usedRange.
 * @returns Object with `values` — a 2D array of cell values (row × column).
 */
export async function getWorksheetRange(
  worksheet: string,
  range?: string
): Promise<{ values: unknown[][] }> {
  const driveId = process.env.SHAREHOLDER_MODEL_DRIVE_ID;
  const itemId = process.env.SHAREHOLDER_MODEL_ITEM_ID;

  if (!driveId || !itemId) {
    throw new Error(
      'Missing SHAREHOLDER_MODEL_DRIVE_ID or SHAREHOLDER_MODEL_ITEM_ID'
    );
  }

  const token = await getSharePointToken();
  const encodedSheet = encodeURIComponent(worksheet);
  const url = range
    ? `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${itemId}/workbook/worksheets/${encodedSheet}/range(address='${encodeURIComponent(range)}')`
    : `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${itemId}/workbook/worksheets/${encodedSheet}/usedRange`;

  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Graph Excel fetch failed for sheet "${worksheet}": ${response.status} ${errorText}`
    );
  }

  const data = await response.json() as { values: unknown[][] };
  logger.info('Worksheet range fetched', {
    worksheet,
    rows: data.values?.length ?? 0,
  });

  return { values: data.values ?? [] };
}

/**
 * ProjectFinTable — Summary data grid for Project COS/Rev Forecast.
 * Columns: Project | Revenue | COS Total | Gross Profit | GP% | Cost/Home
 * Uses the "actual" column from each section as the summary value.
 */
'use client';

import type { ProjectFinData } from '../project-fin/useProjectFinData';

function fZAR(v: number) {
  if (v === 0) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fPct(v: number) {
  return `${(v * 100).toFixed(1)}%`;
}

interface Props {
  fin: ProjectFinData;
}

export function ProjectFinTable({ fin }: Props) {
  const { projects, cos, revenue, totals } = fin;

  const th = 'px-4 py-2.5 text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';
  const thR = `${th} text-right`;

  const rows = projects.map(p => {
    const rev = revenue[p]?.actual ?? 0;
    const cosVal = cos[p]?.actual ?? 0;
    const gross = rev - cosVal;
    const gpPct = rev !== 0 ? gross / rev : 0;
    return { project: p, rev, cosVal, gross, gpPct };
  });

  const totalRev = totals.revenue.actual;
  const totalCos = totals.cos.actual;
  const totalGross = totalRev - totalCos;
  const totalGpPct = totalRev !== 0 ? totalGross / totalRev : 0;

  return (
    <div className="overflow-x-auto rounded-lg border border-gray-700">
      <table className="w-full text-sm border-collapse">
        <thead>
          <tr style={{ backgroundColor: '#1a3a4a' }}>
            <th className={`${th} text-left`} style={{ minWidth: 180 }}>Project</th>
            <th className={thR}>Revenue (R)</th>
            <th className={thR}>COS Total (R)</th>
            <th className={thR}>Gross Profit (R)</th>
            <th className={thR}>GP %</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={r.project} className={i % 2 === 0 ? 'bg-gray-900' : 'bg-gray-800/60'}>
              <td className="px-4 py-2 font-medium text-gray-200">{r.project}</td>
              <td className="px-4 py-2 text-right tabular-nums text-gray-300">{fZAR(r.rev)}</td>
              <td className="px-4 py-2 text-right tabular-nums text-gray-300">{fZAR(r.cosVal)}</td>
              <td className={`px-4 py-2 text-right tabular-nums font-semibold ${r.gross < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                {fZAR(r.gross)}
              </td>
              <td className={`px-4 py-2 text-right tabular-nums ${r.gpPct < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                {fPct(r.gpPct)}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr className="border-t-2 border-gray-500 font-bold" style={{ backgroundColor: '#1a3a4a' }}>
            <td className="px-4 py-2.5 text-white">Total</td>
            <td className="px-4 py-2.5 text-right tabular-nums text-white">{fZAR(totalRev)}</td>
            <td className="px-4 py-2.5 text-right tabular-nums text-white">{fZAR(totalCos)}</td>
            <td className={`px-4 py-2.5 text-right tabular-nums ${totalGross < 0 ? 'text-red-300' : 'text-emerald-300'}`}>
              {fZAR(totalGross)}
            </td>
            <td className={`px-4 py-2.5 text-right tabular-nums ${totalGpPct < 0 ? 'text-red-300' : 'text-emerald-300'}`}>
              {fPct(totalGpPct)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

/**
 * PortfolioTable — Inline-editable project summary table.
 *
 * Editable cells (white bg): Name, PO Count, Rate, Uptake %, Build Duration, Start Date
 * Calculated cells (pale green): FC Activation, Revenue, COS Total, Profit, GP%, Cost/Home
 *
 * Click any editable cell → edit in place → blur → instant recalculate.
 * [Save] button persists all changes to the API.
 */

'use client';

import { useState, useRef, useCallback } from 'react';
import { Save, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import type { ConduitProject, ConduitProjectInputs } from '../types';
import { calcConduit } from '../hooks/useConduitCalc';

// ─── Formatting helpers ────────────────────────────────────────────────────

function fZAR(v: number): string {
  if (!isFinite(v)) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fPct(v: number): string {
  return `${(v * 100).toFixed(1)}%`;
}

function fNum(v: number): string {
  return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0');
}

// ─── Editable cell ────────────────────────────────────────────────────────

interface EditableCellProps {
  value: string | number;
  onCommit: (val: string) => void;
  type?: 'text' | 'number' | 'date' | 'percent';
  align?: 'left' | 'right';
  disabled?: boolean;
}

function EditableCell({ value, onCommit, type = 'number', align = 'right', disabled = false }: EditableCellProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const displayValue = type === 'percent'
    ? `${(Number(value) * 100).toFixed(1)}%`
    : type === 'number'
    ? fNum(Number(value))
    : String(value ?? '');

  const startEdit = () => {
    if (disabled) return;
    const raw = type === 'percent' ? String(Number(value) * 100) : String(value ?? '');
    setDraft(raw);
    setEditing(true);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commit = () => {
    setEditing(false);
    if (draft === String(value)) return;
    const committed = type === 'percent' ? String(Number(draft) / 100) : draft;
    onCommit(committed);
  };

  const tdClass = `px-3 py-2 text-sm ${align === 'right' ? 'text-right' : 'text-left'} bg-white border border-gray-200 cursor-text hover:bg-blue-50 transition-colors`;

  if (editing) {
    return (
      <td className={tdClass} style={{ minWidth: 80 }}>
        <input
          ref={inputRef}
          type={type === 'percent' ? 'number' : type}
          value={draft}
          onChange={e => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={e => { if (e.key === 'Enter') commit(); if (e.key === 'Escape') setEditing(false); }}
          className="w-full bg-transparent outline-none text-sm text-right font-medium text-gray-900"
          step={type === 'percent' ? '0.1' : undefined}
        />
      </td>
    );
  }

  return (
    <td className={tdClass} onClick={startEdit}>
      <span className="font-medium text-gray-900">{displayValue}</span>
    </td>
  );
}

// ─── Calculated cell ──────────────────────────────────────────────────────

function CalcCell({ value, format = 'zar', negative = false }: { value: number; format?: 'zar' | 'pct' | 'num'; negative?: boolean }) {
  const display = format === 'zar' ? fZAR(value) : format === 'pct' ? fPct(value) : fNum(value);
  const color = negative && value < 0 ? 'text-red-600' : negative && value > 0 ? 'text-emerald-700' : 'text-emerald-800';
  return (
    <td className="px-3 py-2 text-sm text-right bg-emerald-50 border border-emerald-100">
      <span className={`font-medium tabular-nums ${color}`}>{display}</span>
    </td>
  );
}

// ─── Main component ───────────────────────────────────────────────────────

interface PortfolioTableProps {
  initialProjects: ConduitProject[];
}

export function PortfolioTable({ initialProjects }: PortfolioTableProps) {
  const [projects, setProjects] = useState<ConduitProject[]>(initialProjects);
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState<Record<string, boolean>>({});
  const [error, setError] = useState<string | null>(null);

  // Deep-update a project field
  const updateProject = useCallback((id: string, updater: (p: ConduitProject) => ConduitProject) => {
    setProjects(prev => prev.map(p => p.id === id ? updater(p) : p));
    setSaved(prev => ({ ...prev, [id]: false }));
  }, []);

  const updateTopLevel = (id: string, field: keyof ConduitProject, raw: string) => {
    updateProject(id, p => ({ ...p, [field]: field === 'po_count' || field === 'build_duration_months' ? Number(raw) : raw }));
  };

  const updateInputs = (id: string, field: keyof ConduitProjectInputs, raw: string) => {
    updateProject(id, p => ({
      ...p,
      inputs_json: { ...p.inputs_json, [field]: Number(raw) },
    }));
  };

  const saveProject = async (project: ConduitProject) => {
    setSaving(prev => ({ ...prev, [project.id]: true }));
    setError(null);
    try {
      const res = await fetch(`/api/conduit/projects/${project.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: project.name,
          po_count: project.po_count,
          start_date: project.start_date,
          build_duration_months: project.build_duration_months,
          inputs_json: project.inputs_json,
          version_label: `Manual save ${new Date().toLocaleString('en-ZA')}`,
        }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { data } = await res.json() as { data: ConduitProject };
      setProjects(prev => prev.map(p => p.id === data.id ? data : p));
      setSaved(prev => ({ ...prev, [project.id]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [project.id]: false })), 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(prev => ({ ...prev, [project.id]: false }));
    }
  };

  // Header style
  const thClass = 'px-3 py-2.5 text-left text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';
  const thRightClass = `${thClass} text-right`;

  return (
    <div className="space-y-4">
      {error && (
        <div className="flex items-center gap-2 text-red-400 bg-red-400/10 border border-red-400/20 rounded px-3 py-2 text-sm">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          {error}
        </div>
      )}

      <div className="overflow-x-auto rounded-lg border border-gray-200 shadow-sm">
        <table className="min-w-max w-full border-collapse text-sm">
          {/* Column group labels */}
          <thead>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              <th className={thClass} colSpan={6}>INPUTS (editable)</th>
              <th className={`${thClass} text-right`} colSpan={6} style={{ backgroundColor: '#1e5440' }}>
                CALCULATED (live)
              </th>
              <th className={thClass} style={{ width: 80 }}></th>
            </tr>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              {/* Editable columns */}
              <th className={thClass} style={{ minWidth: 160 }}>Project</th>
              <th className={thRightClass} style={{ minWidth: 90 }}>PO Count</th>
              <th className={thRightClass} style={{ minWidth: 80 }}>Rate (R)</th>
              <th className={thRightClass} style={{ minWidth: 80 }}>Uptake %</th>
              <th className={thRightClass} style={{ minWidth: 100 }}>Build (mo)</th>
              <th className={thRightClass} style={{ minWidth: 120 }}>Start Date</th>
              {/* Calculated columns */}
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 110 }}>FC Activations</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>Revenue</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>COS Total</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 120 }}>Profit</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 80 }}>GP %</th>
              <th className={`${thRightClass}`} style={{ backgroundColor: '#1e5440', minWidth: 110 }}>Cost / Home</th>
              {/* Actions */}
              <th className={thClass} style={{ minWidth: 72 }}></th>
            </tr>
          </thead>

          <tbody>
            {projects.map(project => {
              const calc = calcConduit(project);
              const isSaving = saving[project.id] ?? false;
              const justSaved = saved[project.id] ?? false;
              return (
                <tr key={project.id} className="hover:bg-gray-50/50">
                  {/* Editable cells */}
                  <EditableCell
                    value={project.name}
                    type="text"
                    align="left"
                    onCommit={v => updateTopLevel(project.id, 'name', v)}
                  />
                  <EditableCell
                    value={project.po_count}
                    onCommit={v => updateTopLevel(project.id, 'po_count', v)}
                  />
                  <EditableCell
                    value={project.inputs_json.rate}
                    onCommit={v => updateInputs(project.id, 'rate', v)}
                  />
                  <EditableCell
                    value={project.inputs_json.uptake}
                    type="percent"
                    onCommit={v => updateInputs(project.id, 'uptake', v)}
                  />
                  <EditableCell
                    value={project.build_duration_months}
                    onCommit={v => updateTopLevel(project.id, 'build_duration_months', v)}
                  />
                  <EditableCell
                    value={project.start_date ?? ''}
                    type="date"
                    align="left"
                    onCommit={v => updateTopLevel(project.id, 'start_date', v)}
                  />

                  {/* Calculated cells */}
                  <CalcCell value={calc.fc_activation} format="num" />
                  <CalcCell value={calc.revenue} />
                  <CalcCell value={calc.cos_total} />
                  <CalcCell value={calc.profit} negative />
                  <CalcCell value={calc.gross_profit_pct} format="pct" negative />
                  <CalcCell value={calc.cost_per_home} />

                  {/* Save button */}
                  <td className="px-2 py-2 text-center bg-white border border-gray-200">
                    <button
                      onClick={() => saveProject(project)}
                      disabled={isSaving || project.is_baseline_locked}
                      className="flex items-center gap-1 px-2 py-1 rounded text-xs font-medium bg-teal-700 hover:bg-teal-600 text-white disabled:opacity-40 transition-colors mx-auto"
                      title={project.is_baseline_locked ? 'Baseline locked' : 'Save changes'}
                    >
                      {isSaving ? (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      ) : justSaved ? (
                        <CheckCircle2 className="w-3 h-3 text-emerald-300" />
                      ) : (
                        <Save className="w-3 h-3" />
                      )}
                      {isSaving ? 'Saving' : justSaved ? 'Saved' : 'Save'}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>

          {/* Totals row */}
          {projects.length > 1 && (() => {
            const totals = projects.reduce((acc, p) => {
              const c = calcConduit(p);
              return {
                po_count: acc.po_count + p.po_count,
                fc_activation: acc.fc_activation + c.fc_activation,
                revenue: acc.revenue + c.revenue,
                cos_total: acc.cos_total + c.cos_total,
                profit: acc.profit + c.profit,
              };
            }, { po_count: 0, fc_activation: 0, revenue: 0, cos_total: 0, profit: 0 });
            const gp_pct = totals.revenue > 0 ? totals.profit / totals.revenue : 0;

            const totalTd = 'px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums';
            return (
              <tfoot>
                <tr style={{ backgroundColor: '#1a3a4a' }}>
                  <td className="px-3 py-2.5 text-sm font-bold text-white" colSpan={2}>TOTAL</td>
                  <td className={totalTd}>{fNum(totals.po_count)}</td>
                  <td colSpan={3}></td>
                  <td className={totalTd}>{fNum(totals.fc_activation)}</td>
                  <td className={totalTd}>{fZAR(totals.revenue)}</td>
                  <td className={totalTd}>{fZAR(totals.cos_total)}</td>
                  <td className={totalTd}>{fZAR(totals.profit)}</td>
                  <td className={totalTd}>{fPct(gp_pct)}</td>
                  <td colSpan={2}></td>
                </tr>
              </tfoot>
            );
          })()}
        </table>
      </div>

      <p className="text-xs text-gray-400">
        Click any white cell to edit. Calculated values update instantly. Press Save to persist.
      </p>
    </div>
  );
}

