function fZAR(v: number): string {
  if (!isFinite(v) || v === 0) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fPct(v: number): string { return `${(v * 100).toFixed(1)}%`; }
function fNum(v: number): string { return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0'); }

interface KpiCardProps {
