/**
 * Conduit module types — project scenario modelling.
 */

export interface ScopeInputs {
  poles: number;
  stringing_m: number;
  pon: number;
}

export interface ServiceRates {
  permissions_per_pole: number;
  poles_each: number;
  stringing_per_m: number;
  optical_per_pon: number;
  activation_each: number;
}

export interface StockRates {
  pole: number;
  cable_per_m: number;
  optical: number;
  activation: number;
}

export interface ExpensesPerMonth {
  ad_hoc: number;
  casuals: number;
  fuel: number;
  overheads: number;
  sales: number;
}

export interface ConduitProjectInputs {
  rate: number;
  uptake: number;
  scope: ScopeInputs;
  service_rates: ServiceRates;
  stock_rates: StockRates;
  expenses_per_month: ExpensesPerMonth;
}

export interface ConduitProject {
  id: string;
  name: string;
  po_count: number;
  start_date: string | null;
  build_duration_months: number;
  inputs_json: ConduitProjectInputs;
  is_baseline_locked: boolean;
  created_at: string;
  updated_at: string;
}

/** Calculated (derived) fields — never stored, always re-derived from inputs */
export interface ConduitCalcResult {
  fc_activation: number;
  revenue: number;
  cos_services: number;
  cos_stock: number;
  cos_expenses: number;
  cos_total: number;
  profit: number;
  gross_profit_pct: number;
  cost_per_home: number;
}

/**
 * useConduitCalc — Pure formula engine for Conduit project calculations.
 * No side effects, no API calls. Input → derived output.
 *
 * COS Formula:
 *   Services = (Poles × PermPerPole) + (Poles × PolesEach) + (Stringing × StringPerM)
 *              + (PON × OptPerPON) + (FCActivations × ActEach)
 *   Stock    = (Poles × PoleStock) + (Stringing × CablePerM)
 *              + (PON × OptStock) + (FCActivations × ActStock)
 *   Expenses = (AdHoc + Casuals + Fuel + Overheads + Sales) × BuildDuration
 *   COS Total = Services + Stock + Expenses
 */

import type { ConduitProject, ConduitCalcResult } from '../types';

export function calcConduit(project: ConduitProject): ConduitCalcResult {
  const { po_count, build_duration_months, inputs_json: inp } = project;
  const { rate, uptake, scope, service_rates: sr, stock_rates: st, expenses_per_month: ex } = inp;

  // Core derivations
  const fc_activation = po_count * uptake;
  const revenue = fc_activation * rate * 12;

  // COS — Services
  const cos_services =
    scope.poles * sr.permissions_per_pole +
    scope.poles * sr.poles_each +
    scope.stringing_m * sr.stringing_per_m +
    scope.pon * sr.optical_per_pon +
    fc_activation * sr.activation_each;

  // COS — Stock
  const cos_stock =
    scope.poles * st.pole +
    scope.stringing_m * st.cable_per_m +
    scope.pon * st.optical +
    fc_activation * st.activation;

  // COS — Expenses (monthly total × build duration)
  const monthly_expenses = ex.ad_hoc + ex.casuals + ex.fuel + ex.overheads + ex.sales;
  const cos_expenses = monthly_expenses * build_duration_months;

  const cos_total = cos_services + cos_stock + cos_expenses;
  const profit = revenue - cos_total;
  const gross_profit_pct = revenue > 0 ? profit / revenue : 0;
  const cost_per_home = po_count > 0 ? cos_total / po_count : 0;

  return {
    fc_activation,
    revenue,
    cos_services,
    cos_stock,
    cos_expenses,
    cos_total,
    profit,
    gross_profit_pct,
    cost_per_home,
  };
}

/** React hook wrapper — memoises calc result when project changes. */
import { useMemo } from 'react';

export function useConduitCalc(project: ConduitProject): ConduitCalcResult {
  return useMemo(() => calcConduit(project), [project]);
}

/**
 * GET    /api/conduit/projects/[id] — fetch single project
 * PUT    /api/conduit/projects/[id] — update project + snapshot version history
 */

import { NextRequest, NextResponse } from 'next/server';
import { getAuth } from '@/lib/auth-mock';
import { neon } from '@neondatabase/serverless';
import type { ConduitProject } from '@/modules/conduit/types';

const sql = neon(process.env.DATABASE_URL!);

interface RouteContext {
  params: { id: string };
}

export async function GET(req: NextRequest, { params }: RouteContext) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const [row] = await sql`
      SELECT id, name, po_count, start_date, build_duration_months,
             inputs_json, is_baseline_locked, created_at, updated_at
      FROM conduit_projects
      WHERE id = ${params.id}
    `;

    if (!row) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    return NextResponse.json({ data: row as ConduitProject });
  } catch (error) {
    console.error('[conduit/projects/[id] GET]', error);
    return NextResponse.json({ error: 'Failed to fetch project' }, { status: 500 });
  }
}

export async function PUT(req: NextRequest, { params }: RouteContext) {
  try {
    const auth = getAuth(req);
    if (!auth?.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await req.json() as Partial<ConduitProject> & { version_label?: string };
    const { name, po_count, start_date, build_duration_months, inputs_json, version_label } = body;

    // Fetch existing to snapshot before update
    const [existing] = await sql`
      SELECT * FROM conduit_projects WHERE id = ${params.id}
    `;

    if (!existing) {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    if (existing.is_baseline_locked) {
      return NextResponse.json({ error: 'Project baseline is locked' }, { status: 409 });
    }

    // Snapshot current state as a version
    const label = version_label ?? `Auto-save ${new Date().toISOString()}`;
    await sql`
      INSERT INTO conduit_project_versions
        (project_id, version_label, inputs_snapshot, created_by)
      VALUES (
        ${params.id},
        ${label},
        ${JSON.stringify(existing.inputs_json)}::jsonb,
        ${auth.userId}
      )
    `;

    // Apply updates (only provided fields)
    const [updated] = await sql`
      UPDATE conduit_projects SET
        name                  = ${name ?? existing.name},
        po_count              = ${po_count ?? existing.po_count},
        start_date            = ${start_date ?? existing.start_date},
        build_duration_months = ${build_duration_months ?? existing.build_duration_months},
        inputs_json           = ${JSON.stringify(inputs_json ?? existing.inputs_json)}::jsonb
      WHERE id = ${params.id}
      RETURNING id, name, po_count, start_date, build_duration_months,
                inputs_json, is_baseline_locked, created_at, updated_at
    `;

    return NextResponse.json({ data: updated as ConduitProject });
  } catch (error) {
    console.error('[conduit/projects/[id] PUT]', error);
    return NextResponse.json({ error: 'Failed to update project' }, { status: 500 });
  }
}

