/**
 * ProjectDetailPanel — Drill-down detail for a Conduit project.
 * Renders 3 forecast tables: Rollout Plan, COS Categories, Revenue.
 */
'use client';

import { useEffect, useState } from 'react';
import { Loader2 } from 'lucide-react';
import { log } from '@/lib/logger';

// ─── Types ──────────────────────────────────────────────────────────────────

interface ForecastRow {
  label: string;
  values: (number | null)[];
  isTotal?: boolean;
}

interface ProjectDetailData {
  projectName: string;
  months: string[];
  rolloutPlan: ForecastRow[];
  cosCategories: ForecastRow[];
  revenueForecast: ForecastRow[];
}

// ─── Formatters ─────────────────────────────────────────────────────────────

function fZAR(v: number | null): string {
  if (v === null || v === 0) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fInt(v: number | null): string {
  if (v === null || v === 0) return '—';
  return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0');
}

// ─── Sub-table ───────────────────────────────────────────────────────────────

interface ForecastTableProps {
  title: string;
  months: string[];
  rows: ForecastRow[];
  format: 'int' | 'zar';
}

function ForecastTable({ title, months, rows, format }: ForecastTableProps) {
  const fmt = (v: number | null) => format === 'zar' ? fZAR(v) : fInt(v);

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs border-collapse min-w-max">
        <thead>
          <tr style={{ backgroundColor: '#1a3a4a' }}>
            <th className="px-3 py-2 text-left text-white font-bold whitespace-nowrap" style={{ minWidth: 180 }}>
              {title}
            </th>
            {months.map(m => (
              <th key={m} className="px-2 py-2 text-right text-white font-semibold whitespace-nowrap" style={{ minWidth: 90 }}>
                {m}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => {
            const isTotal = row.isTotal;
            const rowBg = isTotal ? '#1a3a4a' : i % 2 === 0 ? 'bg-gray-900' : 'bg-gray-800/60';
            return (
              <tr key={row.label} className={typeof rowBg === 'string' && rowBg.startsWith('bg-') ? rowBg : ''} style={typeof rowBg !== 'string' || !rowBg.startsWith('bg-') ? { backgroundColor: rowBg } : {}}>
                <td className={`px-3 py-1.5 whitespace-nowrap ${isTotal ? 'font-bold text-white' : 'text-gray-300'}`}>
                  {row.label}
                </td>
                {row.values.map((v, j) => {
                  const isNeg = typeof v === 'number' && v < 0;
                  return (
                    <td
                      key={j}
                      className={`px-2 py-1.5 text-right tabular-nums ${isTotal ? 'font-bold text-white' : isNeg ? 'text-red-400' : 'text-gray-300'}`}
                      style={isNeg && !isTotal ? { color: '#D13438' } : undefined}
                    >
                      {fmt(v)}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

