/**
 * PortfolioTable — v2 Portfolio with expandable drill-down.
 *
 * Editable: Rate, Uptake %, Build Duration
 * Read-only: PO Count, FC Activations, Revenue, COS Total, Profit, GP%, Cost/Home
 * Expand: click row or chevron → ProjectDetailPanel inline
 */
'use client';

import { useState, useRef, useCallback } from 'react';
import { ChevronRight, ChevronDown, Save, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import type { ConduitProject, ConduitProjectInputs } from '../types';
import { calcConduit } from '../hooks/useConduitCalc';
import { ProjectDetailPanel } from './ProjectDetailPanel';
import { log } from '@/lib/logger';

// ─── Formatters ─────────────────────────────────────────────────────────────

function fZAR(v: number): string {
  if (!isFinite(v) || v === 0) return '—';
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `${v < 0 ? '-' : ''}R\u00a0${s}`;
}

function fPct(v: number): string { return `${(v * 100).toFixed(1)}%`; }
function fNum(v: number): string { return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0'); }

// ─── EditableCell ────────────────────────────────────────────────────────────

interface EditableCellProps {
  value: number;
  onCommit: (val: string) => void;
  type?: 'number' | 'percent';
}

function EditableCell({ value, onCommit, type = 'number' }: EditableCellProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const display = type === 'percent' ? `${(value * 100).toFixed(1)}%` : fNum(value);

  const startEdit = () => {
    setDraft(type === 'percent' ? String(value * 100) : String(value));
    setEditing(true);
    setTimeout(() => inputRef.current?.select(), 0);
  };

  const commit = () => {
    setEditing(false);
    const committed = type === 'percent' ? String(Number(draft) / 100) : draft;
    onCommit(committed);
  };

  if (editing) {
    return (
      <td className="px-3 py-2 text-sm text-right bg-white border border-blue-300" style={{ minWidth: 80 }}>
        <input
          ref={inputRef}
          type="number"
          value={draft}
          onChange={e => setDraft(e.target.value)}
          onBlur={commit}
          onKeyDown={e => { if (e.key === 'Enter') commit(); if (e.key === 'Escape') setEditing(false); }}
          className="w-full bg-transparent outline-none text-sm text-right font-medium text-gray-900"
        />
      </td>
    );
  }

  return (
    <td
      className="px-3 py-2 text-sm text-right bg-white border border-gray-200 cursor-text hover:bg-blue-50 transition-colors"
      style={{ minWidth: 80 }}
      onClick={startEdit}
    >
      <span className="font-medium text-gray-900 tabular-nums">{display}</span>
    </td>
  );
}

// ─── ReadCell ────────────────────────────────────────────────────────────────

function ReadCell({ value, format = 'zar' }: { value: number; format?: 'zar' | 'pct' | 'num' }) {
  const display = format === 'zar' ? fZAR(value) : format === 'pct' ? fPct(value) : fNum(value);
  const isNeg = value < 0;
  const isGoodGP = format === 'pct' && value >= 0.30;
  const isAmberGP = format === 'pct' && value >= 0.10 && value < 0.30;

  let color = 'text-gray-300';
  if (format === 'zar' && isNeg) color = 'text-red-400';
  if (format === 'pct') {
    if (isGoodGP) color = 'text-emerald-400';
    else if (isAmberGP) color = 'text-amber-400';
    else color = 'text-red-400';
  }

  return (
    <td className="px-3 py-2 text-sm text-right bg-gray-800/40 border border-gray-700" style={{ minWidth: 90 }}>
      <span className={`tabular-nums ${color}`}>{display}</span>
    </td>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

interface PortfolioTableProps {
  initialProjects: ConduitProject[];
}

export function PortfolioTable({ initialProjects }: PortfolioTableProps) {
  const [projects, setProjects] = useState<ConduitProject[]>(initialProjects);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [saving, setSaving] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState<Record<string, boolean>>({});
  const [error, setError] = useState<string | null>(null);

  const toggleExpand = (id: string) => {
    setExpanded(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const updateProject = useCallback((id: string, updater: (p: ConduitProject) => ConduitProject) => {
    setProjects(prev => prev.map(p => p.id === id ? updater(p) : p));
    setSaved(prev => ({ ...prev, [id]: false }));
  }, []);

  const updateInputs = (id: string, field: keyof ConduitProjectInputs, raw: string) => {
    updateProject(id, p => ({ ...p, inputs_json: { ...p.inputs_json, [field]: Number(raw) } }));
  };

  const updateDuration = (id: string, raw: string) => {
    updateProject(id, p => ({ ...p, build_duration_months: Number(raw) }));
  };

  const saveProject = async (project: ConduitProject) => {
    setSaving(prev => ({ ...prev, [project.id]: true }));
    setError(null);
    try {
      const res = await fetch(`/api/conduit/projects/${project.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: project.name,
          po_count: project.po_count,
          start_date: project.start_date,
          build_duration_months: project.build_duration_months,
          inputs_json: project.inputs_json,
          version_label: `Save ${new Date().toLocaleString('en-ZA')}`,
        }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { data } = await res.json() as { data: ConduitProject };
      setProjects(prev => prev.map(p => p.id === data.id ? data : p));
      setSaved(prev => ({ ...prev, [project.id]: true }));
      setTimeout(() => setSaved(prev => ({ ...prev, [project.id]: false })), 2000);
    } catch (err) {
      log.error('PortfolioTable save failed', { id: project.id, err: String(err) });
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(prev => ({ ...prev, [project.id]: false }));
    }
  };

  const COLS = 12; // total columns for colspan in expansion row
  const th = 'px-3 py-2.5 text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';

  // Totals
  const totals = projects.reduce((acc, p) => {
    const c = calcConduit(p);
    return {
      po_count: acc.po_count + p.po_count,
      fc_activation: acc.fc_activation + c.fc_activation,
      revenue: acc.revenue + c.revenue,
      cos_total: acc.cos_total + c.cos_total,
      profit: acc.profit + c.profit,
    };
  }, { po_count: 0, fc_activation: 0, revenue: 0, cos_total: 0, profit: 0 });
  const totalGP = totals.revenue > 0 ? totals.profit / totals.revenue : 0;

  return (
    <div className="space-y-3">
      {error && (
        <div className="flex items-center gap-2 text-red-400 bg-red-400/10 border border-red-400/20 rounded px-3 py-2 text-sm">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      <div className="overflow-x-auto rounded-lg border border-gray-700 shadow-sm">
        <table className="min-w-max w-full border-collapse text-sm">
          <thead>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              <th className={th} style={{ width: 32 }}></th>
              <th className={`${th} text-left`} style={{ minWidth: 200 }}>Project Scope — Executable</th>
              <th className={`${th} text-right`} style={{ minWidth: 90 }}>PO Count</th>
              <th className={`${th} text-right`} style={{ minWidth: 80 }}>Rate</th>
              <th className={`${th} text-right`} style={{ minWidth: 80 }}>Uptake</th>
              <th className={`${th} text-right`} style={{ minWidth: 110 }}>FC Activations</th>
              <th className={`${th} text-right`} style={{ minWidth: 120 }}>Revenue</th>
              <th className={`${th} text-right`} style={{ minWidth: 120 }}>COS Total</th>
              <th className={`${th} text-right`} style={{ minWidth: 120 }}>Profit</th>
              <th className={`${th} text-right`} style={{ minWidth: 70 }}>GP%</th>
              <th className={`${th} text-right`} style={{ minWidth: 100 }}>Cost/Home</th>
              <th className={`${th} text-right`} style={{ minWidth: 90 }}>Build Duration</th>
              <th className={th} style={{ width: 72 }}></th>
            </tr>
          </thead>

          <tbody>
            {projects.map((project, i) => {
              const calc = calcConduit(project);
              const isExpanded = expanded.has(project.id);
              const isSaving = saving[project.id] ?? false;
              const justSaved = saved[project.id] ?? false;
              const rowBg = i % 2 === 0 ? '#111827' : '#1f2937';

              return [
                <tr
                  key={project.id}
                  style={{ backgroundColor: rowBg }}
                  className="hover:bg-gray-700/30 transition-colors"
                >
                  {/* Chevron */}
                  <td
                    className="px-2 py-2 text-center cursor-pointer text-gray-400 hover:text-white border border-gray-700"
                    onClick={() => toggleExpand(project.id)}
                  >
                    {isExpanded
                      ? <ChevronDown className="w-4 h-4 inline" />
                      : <ChevronRight className="w-4 h-4 inline" />
                    }
                  </td>
                  {/* Project name (read-only, click to expand) */}
                  <td
                    className="px-3 py-2 text-sm font-medium text-gray-200 border border-gray-700 cursor-pointer hover:text-white"
                    onClick={() => toggleExpand(project.id)}
                  >
                    {project.name}
                  </td>
                  {/* PO Count — read-only */}
                  <td className="px-3 py-2 text-sm text-right bg-gray-800/40 border border-gray-700 text-gray-300 tabular-nums">
                    {fNum(project.po_count)}
                  </td>
                  {/* Rate — editable */}
                  <EditableCell
                    value={project.inputs_json.rate}
                    onCommit={v => updateInputs(project.id, 'rate', v)}
                  />
                  {/* Uptake — editable */}
                  <EditableCell
                    value={project.inputs_json.uptake}
                    type="percent"
                    onCommit={v => updateInputs(project.id, 'uptake', v)}
                  />
                  {/* Calculated read-only */}
                  <ReadCell value={calc.fc_activation} format="num" />
                  <ReadCell value={calc.revenue} />
                  <ReadCell value={calc.cos_total} />
                  <ReadCell value={calc.profit} />
                  <ReadCell value={calc.gross_profit_pct} format="pct" />
                  <ReadCell value={calc.cost_per_home} />
                  {/* Build Duration — editable */}
                  <EditableCell
                    value={project.build_duration_months}
                    onCommit={v => updateDuration(project.id, v)}
                  />
                  {/* Save */}
                  <td className="px-2 py-2 text-center border border-gray-700 bg-gray-900">
                    <button
                      onClick={() => saveProject(project)}
                      disabled={isSaving || project.is_baseline_locked}
                      className="flex items-center gap-1 px-2 py-1 rounded text-xs font-medium bg-teal-700 hover:bg-teal-600 text-white disabled:opacity-40 transition-colors mx-auto"
                    >
                      {isSaving ? <Loader2 className="w-3 h-3 animate-spin" />
                        : justSaved ? <CheckCircle2 className="w-3 h-3 text-emerald-300" />
                        : <Save className="w-3 h-3" />}
                      {isSaving ? 'Saving' : justSaved ? 'Saved' : 'Save'}
                    </button>
                  </td>
                </tr>,

                // Expansion row
                isExpanded && (
                  <tr key={`${project.id}-detail`}>
                    <td colSpan={COLS + 1} className="p-0 border border-gray-600">
                      <ProjectDetailPanel projectId={project.id} projectName={project.name} />
                    </td>
                  </tr>
                ),
              ];
            })}
          </tbody>

          {/* Totals footer */}
          <tfoot>
            <tr style={{ backgroundColor: '#1a3a4a' }}>
              <td colSpan={2} className="px-3 py-2.5 text-sm font-bold text-white">TOTAL</td>
              <td className="px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums">{fNum(totals.po_count)}</td>
              <td colSpan={2}></td>
              <td className="px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums">{fNum(totals.fc_activation)}</td>
              <td className="px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums">{fZAR(totals.revenue)}</td>
              <td className="px-3 py-2.5 text-sm text-right font-bold text-white tabular-nums">{fZAR(totals.cos_total)}</td>
              <td className={`px-3 py-2.5 text-sm text-right font-bold tabular-nums ${totals.profit < 0 ? 'text-red-300' : 'text-emerald-300'}`}>{fZAR(totals.profit)}</td>
              <td className={`px-3 py-2.5 text-sm text-right font-bold tabular-nums ${totalGP < 0 ? 'text-red-300' : 'text-emerald-300'}`}>{fPct(totalGP)}</td>
              <td colSpan={3}></td>
            </tr>
          </tfoot>
        </table>
      </div>

      <p className="text-xs text-gray-500">Click Rate, Uptake %, or Build Duration to edit. Click a row or ▶ to drill down.</p>
    </div>
  );
}
