            const rowBg = isTotal ? '#1a3a4a' : i % 2 === 0 ? 'bg-gray-900' : 'bg-gray-800/60';
            return (
              <tr key={row.label} className={typeof rowBg === 'string' && rowBg.startsWith('bg-') ? rowBg : ''} style={typeof rowBg !== 'string' || !rowBg.startsWith('bg-') ? { backgroundColor: rowBg } : {}}>
                <td className={`px-3 py-1.5 whitespace-nowrap ${isTotal ? 'font-bold text-white' : 'text-gray-300'}`}>
                  {row.label}
