                        : justSaved ? <CheckCircle2 className="w-3 h-3 text-emerald-300" />
                        : <Save className="w-3 h-3" />}
                      {isSaving ? 'Saving' : justSaved ? 'Saved' : 'Save'}
                    </button>
                  </td>
                </tr>,

