/**
 * Analytics Reports Registry
 * Central registry of all available analytics reports.
 * Add new report definitions here and map their components in the client page.
 */

/** Report category types */
export type ReportCategory = 'financial' | 'operational' | 'procurement';

/** Metadata definition for a single analytics report */
export interface ReportDefinition {
  /** Unique report identifier — used as key in REPORT_COMPONENTS map */
  id: string;
  /** Human-readable report name */
  name: string;
  /** Short description shown on the report card */
  description: string;
  /** Logical grouping category */
  category: ReportCategory;
}

// 🟢 WORKING: Registry of all available analytics reports
export const REPORT_REGISTRY: ReportDefinition[] = [
  {
    id: 'revenue-overview',
    name: 'Cashflow Overview',
    description: 'Monthly Cash In, Cash Out and Net from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'project-revenue',
    name: 'Project Revenue',
    description: 'Projected FC Activation count per project from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'expense-pivot',
    name: 'Expense Pivot',
    description: 'Monthly expense breakdown by category — mirrors Excel pivot',
    category: 'financial',
  },
  {
    id: 'project-fin',
    name: 'Project COS/Rev \u2014 Forecast',
    description: 'Project-level cost, revenue and net by month from the Shareholder Model',
    category: 'financial',
  },
  {
    id: 'project-detail',
    name: 'Project Detail',
    description: 'Per-project COS breakdown and financial summary with project slicer',
    category: 'financial',
  },
];

/**
 * GET /api/analytics/reports/project-revenue
 *
 * Returns projected activation revenue per project from the
 * Shareholder Model Excel "Project_Detail" worksheet via SharePoint Graph API.
 *
 * Access restricted to authorised users via RBAC (analytics.reports / view)
 * or direct user-ID allowlist.
 */

import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { createLogger } from '@/lib/logger';
import { verifyToken } from '@/lib/auth/jwt';
import { userHasPermission } from '@/lib/permissions';
import { getWorksheetRange } from '@/lib/graph/sharepoint-excel';

const logger = createLogger('analytics:api:project-revenue');

/** Allowlist — fallback guard independent of RBAC table */
const ALLOWED_USERS = new Set([
  '28ab98c1-df21-48f8-a30a-489cd09a0d39', // Hein
  '7d84184b-2a2b-4fbb-a52e-9815d0e92237', // Lew
]);

export interface ProjectRevenuePoint {
  project: string;
  fcActivation: number;
}

function toNumber(cell: unknown): number {
  if (typeof cell === 'number') return cell;
  if (typeof cell === 'string') return parseFloat(cell) || 0;
  return 0;
}

// 🟢 WORKING: Project revenue GET handler — reads live SharePoint data
export async function GET(_req: NextRequest): Promise<NextResponse> {
  // --- Authentication ---
  const cookieStore = await cookies();
  const token = cookieStore.get('ff_auth_token')?.value;

  if (!token) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
      { status: 401 }
    );
  }

  const payload = await verifyToken(token);
  if (!payload?.sub) {
    return NextResponse.json(
      { success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid token' } },
      { status: 401 }
    );
  }

  const userId = payload.sub;

  // --- Authorisation ---
  const hasAccess = await userHasPermission(userId, 'analytics.reports', 'view');
  if (!hasAccess && !ALLOWED_USERS.has(userId)) {
    return NextResponse.json(
      {
        success: false,
        error: { code: 'FORBIDDEN', message: 'Access restricted to authorised users' },
      },
      { status: 403 }
    );
  }

  logger.info('Project revenue requested', { userId });

  try {
    const { values } = await getWorksheetRange('Project_Detail');

    if (!values || values.length < 4) {
      throw new Error('Project_Detail sheet returned insufficient data');
    }

    // Header row is index 2 (row 3):
    // ["","","","Project Scope - Original","PO Count","Rate","Uptake","FC Activation",...]
    // col 3 = project name, col 7 = FC Activation
    const PROJECT_COL = 3;
    const FC_ACTIVATION_COL = 7;

    // Data starts at index 3 (row 4)
    const dataRows = values.slice(3);

    const data: ProjectRevenuePoint[] = [];

    for (const row of dataRows) {
      const typedRow = row as unknown[];
      const project = String(typedRow[PROJECT_COL] ?? '').trim();
      if (!project || project === 'Project Scope - Original') continue;

      const fcActivation = toNumber(typedRow[FC_ACTIVATION_COL]);
      if (fcActivation <= 0) continue;

      data.push({ project, fcActivation });
    }

    return NextResponse.json({
      success: true,
      data,
      meta: {
        generatedAt: new Date().toISOString(),
        projectCount: data.length,
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    logger.error('Project revenue fetch failed', { error: message });

    return NextResponse.json(
      { success: false, error: { code: 'INTERNAL_ERROR', message } },
      { status: 500 }
    );
  }
}

/**
 * useProjectRevenueData — React Query hook for the Project Revenue report.
 * Fetches projected FC Activation values per project from SharePoint via the API.
 */

import { useQuery } from '@tanstack/react-query';

export interface ProjectRevenuePoint {
  project: string;
  fcActivation: number;
}

export interface ProjectRevenueResponse {
  success: boolean;
  data: ProjectRevenuePoint[];
  meta: {
    generatedAt: string;
    projectCount: number;
  };
}

interface ApiErrorBody {
  error?: {
    message?: string;
  };
}

async function fetchProjectRevenue(): Promise<ProjectRevenueResponse> {
  const res = await fetch('/api/analytics/reports/project-revenue');
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    throw new Error(body.error?.message ?? 'Failed to load project revenue data');
  }
  return res.json() as Promise<ProjectRevenueResponse>;
}

// 🟢 WORKING: React Query hook with 5-minute cache
export function useProjectRevenueData() {
  return useQuery<ProjectRevenueResponse, Error>({
    queryKey: ['analytics', 'project-revenue'],
    queryFn: fetchProjectRevenue,
    staleTime: 5 * 60 * 1000,
  });
}

/**
 * ProjectRevenue — FC Activation per project.
 * Table tab: data grid (Project | FC Activations)
 * Charts tab: horizontal bar chart
 */

'use client';

import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts';
import { useProjectRevenueData } from './useProjectRevenueData';
import { AlertCircle, Loader2 } from 'lucide-react';
import { ReportTabLayout } from '../ReportTabLayout';
import { ProjectRevenueTable } from '../tables/ProjectRevenueTable';

// 🟢 WORKING: Project Revenue — table grid + bar chart
export default function ProjectRevenue() {
  const { data, isLoading, error } = useProjectRevenueData();

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64 text-gray-400">
        <Loader2 className="w-6 h-6 animate-spin mr-2" />
        Loading project data&hellip;
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center gap-2 text-red-400 p-4">
        <AlertCircle className="w-5 h-5 flex-shrink-0" />
        <span>{error.message}</span>
      </div>
    );
  }

  const chartData = data?.data ?? [];
  const projectCount = data?.meta.projectCount ?? 0;

  return (
    <ReportTabLayout
      tableContent={<ProjectRevenueTable rows={chartData} />}
      chartsContent={
        <div className="space-y-4">
          <div className="flex items-center gap-6">
            <div>
              <p className="text-xs text-gray-400 uppercase tracking-wider">Projects</p>
              <p className="text-2xl font-bold text-white">{projectCount}</p>
            </div>
            <div>
              <p className="text-xs text-gray-400 uppercase tracking-wider">Source</p>
              <p className="text-sm font-medium text-blue-400">Shareholder Model (live)</p>
            </div>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ top: 4, right: 24, bottom: 4, left: 140 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#374151" horizontal={false} />
                <XAxis type="number" tick={{ fill: '#9CA3AF', fontSize: 11 }} axisLine={{ stroke: '#4B5563' }} tickLine={false} />
                <YAxis type="category" dataKey="project" tick={{ fill: '#9CA3AF', fontSize: 11 }} axisLine={false} tickLine={false} width={135} />
                <Tooltip
                  contentStyle={{ backgroundColor: '#1F2937', border: '1px solid #374151', borderRadius: '6px', color: '#F9FAFB' }}
                  formatter={(value: number) => [value.toLocaleString(), 'FC Activation']}
                />
                <Bar dataKey="fcActivation" fill="#8B5CF6" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      }
    />
  );
}

/**
 * ProjectRevenueTable — Data grid for the Project Revenue report.
 * Columns: Project | FC Activations | Annual Revenue (R)
 * Note: Homes Passed and Uptake% are not in the current API response;
 * showing what is available. Can be extended when API adds those fields.
 */
'use client';

import type { ProjectRevenuePoint } from '../project-revenue/useProjectRevenueData';

function fZAR(v: number) {
  const abs = Math.abs(Math.round(v));
  const s = abs.toLocaleString('en-ZA').replace(/,/g, '\u00a0');
  return `R\u00a0${s}`;
}

function fNum(v: number) {
  return Math.round(v).toLocaleString('en-ZA').replace(/,/g, '\u00a0');
}

interface Props {
  rows: ProjectRevenuePoint[];
}

export function ProjectRevenueTable({ rows }: Props) {
  const totalActivations = rows.reduce((s, r) => s + r.fcActivation, 0);

  const th = 'px-4 py-2.5 text-left text-xs font-bold text-white uppercase tracking-wide whitespace-nowrap';
  const thR = `${th} text-right`;

  return (
    <div className="overflow-x-auto rounded-lg border border-gray-700">
      <table className="w-full text-sm border-collapse">
        <thead>
          <tr style={{ backgroundColor: '#1a3a4a' }}>
            <th className={th} style={{ minWidth: 180 }}>Project</th>
            <th className={thR}>FC Activations</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={r.project} className={i % 2 === 0 ? 'bg-gray-900' : 'bg-gray-800/60'}>
              <td className="px-4 py-2 text-gray-200 font-medium">{r.project}</td>
              <td className="px-4 py-2 text-right tabular-nums text-gray-300">{fNum(r.fcActivation)}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr className="border-t-2 border-gray-500 font-bold" style={{ backgroundColor: '#1a3a4a' }}>
            <td className="px-4 py-2.5 text-white">Total</td>
            <td className="px-4 py-2.5 text-right tabular-nums text-white">{fNum(totalActivations)}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

/**
 * SharePoint Excel utility — reads ranges from the Shareholder Model workbook
 * via Microsoft Graph API using SHAREPOINT_* credentials (separate app from GRAPH_*).
 */

import { createLogger } from '@/lib/logger';

const logger = createLogger('graph:sharepoint-excel');

interface TokenCache {
  token: string;
  expiresAt: number;
}

/** Module-level token cache — survives across requests within the same Node.js process */
let spTokenCache: TokenCache | null = null;

/**
 * Acquires a Graph API access token using the SHAREPOINT_* app credentials.
 * Caches the token and refreshes 5 minutes before expiry.
 */
export async function getSharePointToken(): Promise<string> {
  if (spTokenCache && spTokenCache.expiresAt > Date.now() + 300_000) {
    return spTokenCache.token;
  }

  const tenantId = process.env.SHAREPOINT_TENANT_ID;
  const clientId = process.env.SHAREPOINT_CLIENT_ID;
  const clientSecret = process.env.SHAREPOINT_CLIENT_SECRET;

  if (!tenantId || !clientId || !clientSecret) {
    throw new Error(
      'Missing SharePoint credentials: SHAREPOINT_TENANT_ID, SHAREPOINT_CLIENT_ID, SHAREPOINT_CLIENT_SECRET required'
    );
  }

  const tokenUrl = `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`;
  const params = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  });

  const response = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`SharePoint OAuth failed: ${response.status} ${errorText}`);
  }

  const data = await response.json() as { access_token: string; expires_in: number };
  spTokenCache = {
    token: data.access_token,
    expiresAt: Date.now() + data.expires_in * 1000,
  };

  logger.info('SharePoint access token acquired', { expiresIn: data.expires_in });
  return spTokenCache.token;
}

/**
 * Fetches a worksheet's used range (or a specific address range) from the
 * Shareholder Model Excel file.
 *
 * @param worksheet - Worksheet name, e.g. "Financial Summary"
 * @param range - Optional A1-notation range, e.g. "A1:Z100". Defaults to usedRange.
 * @returns Object with `values` — a 2D array of cell values (row × column).
 */
export async function getWorksheetRange(
  worksheet: string,
  range?: string
): Promise<{ values: unknown[][] }> {
  const driveId = process.env.SHAREHOLDER_MODEL_DRIVE_ID;
  const itemId = process.env.SHAREHOLDER_MODEL_ITEM_ID;

  if (!driveId || !itemId) {
    throw new Error(
      'Missing SHAREHOLDER_MODEL_DRIVE_ID or SHAREHOLDER_MODEL_ITEM_ID'
    );
  }

  const token = await getSharePointToken();
  const encodedSheet = encodeURIComponent(worksheet);
  const url = range
    ? `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${itemId}/workbook/worksheets/${encodedSheet}/range(address='${encodeURIComponent(range)}')`
    : `https://graph.microsoft.com/v1.0/drives/${driveId}/items/${itemId}/workbook/worksheets/${encodedSheet}/usedRange`;

  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `Graph Excel fetch failed for sheet "${worksheet}": ${response.status} ${errorText}`
    );
  }

  const data = await response.json() as { values: unknown[][] };
  logger.info('Worksheet range fetched', {
    worksheet,
    rows: data.values?.length ?? 0,
  });

  return { values: data.values ?? [] };
}

