  items: CostCentreRevenueItem[];
  subtotal: number;
}

function groupByTier1(rows: CostCentreRevenueItem[]): Tier1Group[] {
  const map = new Map<string, CostCentreRevenueItem[]>();
  for (const row of rows) {
    const existing = map.get(row.tier1);
